// An update downloads only what changed: a file whose bytes in an older cache of this app hash to the same SHA-256 is
// copied over from there (this also works from versions that did not know about it). An install that breaks off
// resumes where it stopped, since the cache name is the version. The page is told what was fetched and what reused.
const hex = buf => [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('');
self.addEventListener('install', e => {
  e.waitUntil((async () => {
    const c = await caches.open(CACHE), olds = [];
    for (const k of await caches.keys()) if (k.startsWith('jejumap-') && k !== CACHE) olds.push(await caches.open(k));
    const todo = FILES.slice(), stat = {fetched: 0, reused: 0, kept: 0, bytes: 0};
    const one = async ([path, sum]) => {
      const url = new URL(path, self.registration.scope).href;
      if (await c.match(url, {ignoreVary: true})) { stat.kept++; return; }
      for (const o of olds) {
        const r = await o.match(url, {ignoreVary: true});
        if (r && hex(await crypto.subtle.digest('SHA-256', await r.clone().arrayBuffer())) === sum) { await c.put(url, r); stat.reused++; return; }
      }
      const res = await fetch(new Request(url, {cache: 'reload'}));
      if (!res.ok) throw new Error(path + ' ' + res.status);
      stat.bytes += +(res.headers.get('content-length') || 0);
      await c.put(url, res); stat.fetched++;
    };
    await Promise.all(Array.from({length: 6}, async () => { while (todo.length) await one(todo.shift()); }));
    for (const cl of await self.clients.matchAll({includeUncontrolled: true})) cl.postMessage(Object.assign({type: 'sw-installed', version: VERSION}, stat));
  })());
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k.startsWith('jejumap-') && k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});
self.addEventListener('message', e => { if (e.data === 'skipWaiting') self.skipWaiting(); });
// Same-origin GETs come from the cache first (the network only for something not cached). Anything else, such as
// the address search at Esri, goes to the network untouched. Lookups are exact: a search-ignoring match makes Chrome
// open every cached entry for every request, which took minutes on a phone. Opening the app is always the app shell.
let cacheP = null;
const cache = () => cacheP || (cacheP = caches.open(CACHE));
self.addEventListener('fetch', e => {
  const req = e.request, url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== self.location.origin) return;
  e.respondWith(cache().then(async c => {
    let hit = await c.match(req.mode === 'navigate' ? './' : req, {ignoreVary: true});
    if (!hit && url.search) hit = await c.match(url.origin + url.pathname, {ignoreVary: true});
    return hit || fetch(req);
  }));
});
